(335733, 25851, 7889, '<td valign="top">Like this a lot - love the shadow and the grain - my top vote</td>', 'Like this a lot - love the shadow and the grain - my top vote', '2003-06-23 15:27:30.000000', NULL, 1),
(335745, 25962, 8732, '<td valign="top">Wow. This is really great because you''ve captured the lights, motion, colors, and atmosphere of a concert without making me dizzy! I like the guitarist at the front is still pretty sharp despite the movement around him.</td>', 'Wow. This is really great because you''ve captured the lights, motion, colors, and atmosphere of a concert without making me dizzy! I like the guitarist at the front is still pretty sharp despite the movement around him.', '2003-06-23 16:19:12.000000', NULL, 1),
(335747, 25851, 8732, '<td valign="top">Its very grainy, but i suppose that was the effect you were going for, and it does work very well.  Its a solid photo technically, but I think the composition is just great. The lighting and shadows are wonderful. The crop along the top sort of bothers me, since you can''t see her head, but I think the fact that you can see her head in the shadow  makes up for it.  good job.</td>', 'Its very grainy, but i suppose that was the effect you were going for, and it does work very well.  Its a solid photo technically, but I think the composition is just great. The lighting and shadows are wonderful. The crop along the top sort of bothers me, since you can''t see her head, but I think the fact that you can see her head in the shadow  makes up for it.  good job.', '2003-06-23 16:25:12.000000', NULL, 1),
(335761, 25962, 9131, '<td valign="top">i love it!  the motion combined with the in focus guitarist is great.</td>', 'i love it!  the motion combined with the in focus guitarist is great.', '2003-06-23 17:05:40.000000', NULL, 1),
(335762, 25976, 5767, '<td valign="top">Great execution of the assignment and fantastic image.  The tones are amazingly varied with some excellent and crisp detail.</td>', 'Great execution of the assignment and fantastic image.  The tones are amazingly varied with some excellent and crisp detail.', '2003-06-23 17:06:26.000000', NULL, 1),
(335763, 25602, 5767, '<td valign="top">Timely and relevant image.  This isn''t just a good entry it''s a story - that''s what I enjoyed about this photograph.</td>', 'Timely and relevant image.  This isn''t just a good entry it''s a story - that''s what I enjoyed about this photograph.', '2003-06-23 17:07:32.000000', NULL, 1),
