(336031, 25320, 8953, '<td valign="top">Ouch...I feel someones pain...Great shot</td>', 'Ouch...I feel someones pain...Great shot', '2003-06-24 01:07:11.000000', NULL, 1),
(336033, 25976, 8953, '<td valign="top">I work at a dealership Myself...and even had thoughts of this, but, you did a better job than I think I would have...you even got that "Low key" thing down:) 9</td>', 'I work at a dealership Myself...and even had thoughts of this, but, you did a better job than I think I would have...you even got that "Low key" thing down:) 9', '2003-06-24 01:09:22.000000', NULL, 1),
