(336127, 25970, 8760, '<td valign="top">Nice colors, very lively...one of my top picks !</td>', 'Nice colors, very lively...one of my top picks !', '2003-06-24 05:02:52.000000', NULL, 1),
(336131, 25960, 2337, '<td valign="top">The slope of the horizon is very distracting to me.  Nice composition otherwise.</td>', 'The slope of the horizon is very distracting to me.  Nice composition otherwise.', '2003-06-24 05:12:01.000000', NULL, 1),
(336133, 25242, 2337, '<td valign="top">The busy background gets in the way of an otherwise wonderful shot.  Could you have used a shallower dof?  I know it''s not always possible.</td>', 'The busy background gets in the way of an otherwise wonderful shot.  Could you have used a shallower dof?  I know it''s not always possible.', '2003-06-24 05:13:43.000000', NULL, 1),
(336136, 25906, 2337, '<td valign="top">Very nice skyscape, but I think you missed the idea behind the challenge.  Also I think it would be a better shot if you could have found a way to eliminate the bushes in the foreground without losing the canoe... But that''s just me...</td>', 'Very nice skyscape, but I think you missed the idea behind the challenge.  Also I think it would be a better shot if you could have found a way to eliminate the bushes in the foreground without losing the canoe... But that''s just me...', '2003-06-24 05:17:28.000000', NULL, 1),
(336137, 25984, 2337, '<td valign="top">Nice catch... I hope you helped her out for helping you with the image :)</td>', 'Nice catch... I hope you helped her out for helping you with the image :)', '2003-06-24 05:18:38.000000', NULL, 1),
(336205, 25980, 8987, '<td valign="top">Very nice composition. 10 points.</td>', 'Very nice composition. 10 points.', '2003-06-24 08:23:40.000000', NULL, 1),
(336208, 25425, 5176, '<td valign="top">There''s too much wasted dark space in the foreground, those lights look really interesting its a pity you couldn''t get closer to the people to show more detail</td>', 'There''s too much wasted dark space in the foreground, those lights look really interesting its a pity you couldn''t get closer to the people to show more detail', '2003-06-24 08:49:18.000000', NULL, 1),
(336221, 25928, 5728, '<td valign="top">Funny! Nice B&amp;W pic, only the shadow at the base of the statue is a little distracting - 8.</td>', 'Funny! Nice B&W pic, only the shadow at the base of the statue is a little distracting - 8.', '2003-06-24 09:23:28.000000', NULL, 1),
(336326, 25906, 5728, '<td valign="top">This would be an excellent night shot location, have you ever tried it? I bet that skyline would look great lit up. This photo doesn''t have the same impact as a night shot would, although this is still good.</td>', 'This would be an excellent night shot location, have you ever tried it? I bet that skyline would look great lit up. This photo doesn''t have the same impact as a night shot would, although this is still good.', '2003-06-24 11:55:36.000000', NULL, 1),
(336327, 25924, 5728, '<td valign="top">Did he see you taking his photo? It''s the only policeman shot I''ve come across so far. He does seem a little centered to me, otherwise good.</td>', 'Did he see you taking his photo? It''s the only policeman shot I''ve come across so far. He does seem a little centered to me, otherwise good.', '2003-06-24 11:56:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(336328, 25955, 5728, '<td valign="top">At the first glance I thought she was showing you the birdie :-) The shadow in the lower left hand corner is a little bothersome.</td>', 'At the first glance I thought she was showing you the birdie :-) The shadow in the lower left hand corner is a little bothersome.', '2003-06-24 11:58:03.000000', NULL, 1),
(336330, 25952, 5728, '<td valign="top">The subject is good but for some reason the whole image looks a little washed out. Maybe an increase in the saturation levels might have corrected this a little.</td>', 'The subject is good but for some reason the whole image looks a little washed out. Maybe an increase in the saturation levels might have corrected this a little.', '2003-06-24 11:59:57.000000', NULL, 1),
(336332, 25242, 5728, '<td valign="top">Good capture. I like the way you got her with that strand of hair coming down her face!</td>', 'Good capture. I like the way you got her with that strand of hair coming down her face!', '2003-06-24 12:01:08.000000', NULL, 1),
(336334, 25958, 7966, '<td valign="top">i like this one a lot. it''s funny and the photo is good too</td>', 'i like this one a lot. it''s funny and the photo is good too', '2003-06-24 12:05:28.000000', NULL, 1),
(336335, 25927, 7966, '<td valign="top">the composition is creative. the lighting is superb. i like the little touches of color in her nails and eye. good job</td>', 'the composition is creative. the lighting is superb. i like the little touches of color in her nails and eye. good job', '2003-06-24 12:10:02.000000', NULL, 1),
(336339, 25962, 7966, '<td valign="top">this photo feels loud and chaotic, i like the bright colored lights and the movement that was captured but i think the center subject could have been toned down just a bit. rock on!</td>', 'this photo feels loud and chaotic, i like the bright colored lights and the movement that was captured but i think the center subject could have been toned down just a bit. rock on!', '2003-06-24 12:14:38.000000', NULL, 1),
(336340, 25851, 7966, '<td valign="top">this one captured my attention. i like how you cropped the photo. i also like the effect of the spot light on her and the shadow that she is casting. good one!</td>', 'this one captured my attention. i like how you cropped the photo. i also like the effect of the spot light on her and the shadow that she is casting. good one!', '2003-06-24 12:17:41.000000', NULL, 1),
(336357, 25962, 7543, '<td valign="top">Útgáfutónleikar Maus?</td>', 'Útgáfutónleikar Maus?', '2003-06-24 12:59:56.000000', NULL, 1),
(336358, 25970, 7543, '<td valign="top">Flottir litir, hvar er þetta?</td>', 'Flottir litir, hvar er þetta?', '2003-06-24 13:03:43.000000', NULL, 1),
(336463, 25976, 2130, '<td valign="top">wonderful, should get a ribbon...congrats on a job well done</td>', 'wonderful, should get a ribbon...congrats on a job well done', '2003-06-24 15:43:19.000000', NULL, 1),
(336515, 25967, 2587, '<td valign="top">Absolutely beautiful color! Great composition and (I assume) natural light. Nice capture of the mood and sense of motion in the hand. Love it!</td>', 'Absolutely beautiful color! Great composition and (I assume) natural light. Nice capture of the mood and sense of motion in the hand. Love it!', '2003-06-24 16:58:27.000000', NULL, 1),
(336517, 25960, 7613, '<td valign="top">This shot does not seem to be level...The focus seems a bit soft as well..</td>', 'This shot does not seem to be level...The focus seems a bit soft as well..', '2003-06-24 17:06:17.000000', NULL, 1),
(336518, 25984, 2587, '<td valign="top">Very nice capture. I would''ve liked to see it with a smaller DOF to focus only on the face and blur the wall and writing in the back as well as some of the blanket. Great color!</td>', 'Very nice capture. I would''ve liked to see it with a smaller DOF to focus only on the face and blur the wall and writing in the back as well as some of the blanket. Great color!', '2003-06-24 17:06:22.000000', NULL, 1),
(336581, 25967, 3669, '<td valign="top">Very nice photo!  Definately someone at work.  I''m curious as to what she is cutting.  I like how she is smiling, like she''s proud to have her picture made.  The yellow tapestry in the background is a little distracting, but other than that, a well put together picture.  9  Good luck in the challenge.</td>', 'Very nice photo!  Definately someone at work.  I''m curious as to what she is cutting.  I like how she is smiling, like she''s proud to have her picture made.  The yellow tapestry in the background is a little distracting, but other than that, a well put together picture.  9  Good luck in the challenge.', '2003-06-24 18:57:26.000000', NULL, 1),
(336587, 25845, 3669, '<td valign="top">This looks like this image was taken from one of the mirrors in the casino.  Am I right?  Angle just seems a bit akward, especially since there aren''t people filling the chairs in the middle.  Also, seems just a tad over sharpened to me.  5</td>', 'This looks like this image was taken from one of the mirrors in the casino.  Am I right?  Angle just seems a bit akward, especially since there aren''t people filling the chairs in the middle.  Also, seems just a tad over sharpened to me.  5', '2003-06-24 19:00:59.000000', NULL, 1),
(336593, 25980, 3669, '<td valign="top">Very nice silohette (sp?) picture.  I like how the setting sun refects in his glasses.  8  Good luck in the challenge</td>', 'Very nice silohette (sp?) picture.  I like how the setting sun refects in his glasses.  8  Good luck in the challenge', '2003-06-24 19:04:59.000000', NULL, 1),
(336599, 25859, 3669, '<td valign="top">Very good subject for this challenge.  Seems this photo is quite blurred and an attempt was made to sharpen.  Perhaps also a little over saturated.  Just doesn''t seem right.   4  Good luck in the challenge.</td>', 'Very good subject for this challenge.  Seems this photo is quite blurred and an attempt was made to sharpen.  Perhaps also a little over saturated.  Just doesn''t seem right.   4  Good luck in the challenge.', '2003-06-24 19:08:09.000000', NULL, 1),
(336605, 25511, 3669, '<td valign="top">Nice clear picture and definately meets the challenge.  Might have been better to take the picture the other way or at an angle where you can see the faces of the men, but this works okay too.  7  Good luck in the challenge.</td>', 'Nice clear picture and definately meets the challenge.  Might have been better to take the picture the other way or at an angle where you can see the faces of the men, but this works okay too.  7  Good luck in the challenge.', '2003-06-24 19:10:52.000000', NULL, 1),
(336611, 25825, 3669, '<td valign="top">I''m not so sure I like the angle of the shot.  Otherwise a very nice photo of a working person on the job.  Definately meets challenge.  6 Good luck in the challenge.</td>', 'I''m not so sure I like the angle of the shot.  Otherwise a very nice photo of a working person on the job.  Definately meets challenge.  6 Good luck in the challenge.', '2003-06-24 19:13:56.000000', NULL, 1),
(336617, 25960, 3669, '<td valign="top">It looks cold here.  Perhaps it''s the lighting or it just plain was a cold day.  This picture could probably have been in better focus.  I''m not able to read the sign.  You did meet challenge, however, it might have been nice to see the front of the lifeguard stand.  5 Good luck in the challenge.</td>', 'It looks cold here.  Perhaps it''s the lighting or it just plain was a cold day.  This picture could probably have been in better focus.  I''m not able to read the sign.  You did meet challenge, however, it might have been nice to see the front of the lifeguard stand.  5 Good luck in the challenge.', '2003-06-24 19:17:26.000000', NULL, 1),
(336622, 25973, 3669, '<td valign="top">Men at work.  Definately meets challenge.  I do think it would have been better in color.  The sepia tone just doesn''t seem to go here.  5  Good luck in the challenge.</td>', 'Men at work.  Definately meets challenge.  I do think it would have been better in color.  The sepia tone just doesn''t seem to go here.  5  Good luck in the challenge.', '2003-06-24 19:19:22.000000', NULL, 1),
(336627, 25970, 3669, '<td valign="top">I really like the colors in this picture.  Definately meets challenge.  Only thing that might have completed this picture would have been to see some fish.  8  Good luck in the challenge.</td>', 'I really like the colors in this picture.  Definately meets challenge.  Only thing that might have completed this picture would have been to see some fish.  8  Good luck in the challenge.', '2003-06-24 19:21:33.000000', NULL, 1),
(336630, 25928, 3669, '<td valign="top">Nice take on the challenge.  I like the humor.  :-)  Definately is doing good at his job.  8  Good luck!</td>', 'Nice take on the challenge.  I like the humor.  :-)  Definately is doing good at his job.  8  Good luck!', '2003-06-24 19:23:35.000000', NULL, 1),
(336681, 25928, 7504, '<td valign="top">I like this shot so much, for a different challenge I''d give it a 10, but it seems a stretch here.  Sorry.  6</td>', 'I like this shot so much, for a different challenge I''d give it a 10, but it seems a stretch here.  Sorry.  6', '2003-06-24 20:49:19.000000', NULL, 1),
(336682, 25984, 7504, '<td valign="top">This shot is beautifully done, my favorite of the challenge.  Good luck!</td>', 'This shot is beautifully done, my favorite of the challenge.  Good luck!', '2003-06-24 20:49:47.000000', NULL, 1),
(336683, 25957, 7504, '<td valign="top">Good choice of b/w, it makes everything look like chrome.</td>', 'Good choice of b/w, it makes everything look like chrome.', '2003-06-24 20:50:27.000000', NULL, 1),
(336685, 25967, 7504, '<td valign="top">Great shot, her expression is classic.  Fits the challenge well. 8</td>', 'Great shot, her expression is classic.  Fits the challenge well. 8', '2003-06-24 20:51:17.000000', NULL, 1),
(336686, 25320, 7504, '<td valign="top">Well, this one certainly has an impact.  Doesn''t want to make me look too long.  ; )</td>', 'Well, this one certainly has an impact.  Doesn''t want to make me look too long.  ; )', '2003-06-24 20:52:17.000000', NULL, 1),
