(336784, 25967, 6600, '<td valign="top">Very short DOF... like the subject, lighting, and background.  Nice.</td>', 'Very short DOF... like the subject, lighting, and background.  Nice.', '2003-06-24 23:14:10.000000', NULL, 1),
(336786, 25969, 6600, '<td valign="top">Nicely detailed pic with good exposure, but a bit busy.</td>', 'Nicely detailed pic with good exposure, but a bit busy.', '2003-06-24 23:16:08.000000', NULL, 1),
