(336811, 25962, 6600, '<td valign="top">Stationary items are sharp and well exposed, nice color.  Not sure I like the effect of all the motion thoughout the entire shot.</td>', 'Stationary items are sharp and well exposed, nice color.  Not sure I like the effect of all the motion thoughout the entire shot.', '2003-06-24 23:50:20.000000', NULL, 1),
(336819, 25962, 7838, '<td valign="top">very nice.  i like the "motion" from the long exposure.</td>', 'very nice.  i like the "motion" from the long exposure.', '2003-06-25 00:05:23.000000', NULL, 1),
