(339632, 25980, 2000, '<td valign="top">The chest hair really makes this shot... the dark works well here, as seeing the person more clearly probably would detract from this.</td>', 'The chest hair really makes this shot... the dark works well here, as seeing the person more clearly probably would detract from this.', '2003-06-26 23:15:17.000000', NULL, 1),
(339635, 25825, 2000, '<td valign="top">So nice to see you got the horse to smile, since the officer isn''t.  Not bad.</td>', 'So nice to see you got the horse to smile, since the officer isn''t.  Not bad.', '2003-06-26 23:15:55.000000', NULL, 1),
(339637, 25934, 2000, '<td valign="top">Puns... can''t live with ''em, but we have to for titles like that.  Photo meets challenge, looks good, and no compaints from me.</td>', 'Puns... can''t live with ''em, but we have to for titles like that.  Photo meets challenge, looks good, and no compaints from me.', '2003-06-26 23:17:15.000000', NULL, 1),
(339743, 25973, 8682, '<td valign="top">I like this picture... Beatiful, and love the angle</td>', 'I like this picture... Beatiful, and love the angle', '2003-06-27 01:42:31.000000', NULL, 1),
(339745, 25881, 8682, '<td valign="top">I think it was better if the man of the background didn´t stay there... But, it´s only my opinion. Good work</td>', 'I think it was better if the man of the background didn´t stay there... But, it´s only my opinion. Good work', '2003-06-27 01:44:31.000000', NULL, 1),
